def _windowed_running_min(iterator, maxlen):
    it = iter(iterator)
    window = deque(maxlen=maxlen)

    for value in it:
        window.append(value)
        yield min(window)

def _windowed_running_max(iterator, maxlen):
    it = iter(iterator)
    window = deque(maxlen=maxlen)

    for value in it:
        window.append(value)
        yield max(window)

