# class: isoparser
def isoparse(self, dt_str):
    components, pos = self._parse_isodate(dt_str)

    if len(dt_str) > pos:
        if self._sep is None or dt_str[pos:pos + 1] == self._sep:
            components += self._parse_isotime(dt_str[pos + 1:])
        else:
            raise ValueError('String contains unknown ISO components')

    dt = datetime(*components)

    # Handle 24:00 case - it should roll to next day at 00:00
    if len(dt_str) > pos and b'T24:00' in dt_str:
        # Check if the time component is exactly 24:00:00
        time_part = dt_str[pos + 1:] if pos < len(dt_str) else b''
        if time_part.startswith(b'24:00'):
            dt = dt + timedelta(days=1)

    return dt

